            continue
        if (nx, ny) in obs:
            continue
        dt = cheb(nx, ny, tx, ty)
        do = cheb(nx, ny, ox, oy)
        # Prefer smaller dt; then larger separation from opponent; then deterministic tie.
        key = (dt, -(do), (nx - sx, ny - sy), nx, ny)
        candidates.append((key, dx, dy))
    if not candidates:
        return [0, 0]
    candidates.sort(key=lambda z: z[0])
    return [int(candidates[0][1]), int(candidates[0][2])]

